<script setup lang="ts">
import { invoke } from "@tauri-apps/api/core";
import { computed, onMounted, ref } from "vue";
import { History, RefreshCw } from "lucide-vue-next";
import PaginationControls from "../components/PaginationControls.vue";
interface Movement { id: number; product_name: string; variant_name: string; movement_type: string; quantity: number; stock_after: number; moved_at: string; reason: string | null; reference: string | null }
interface Sale { id: number; reference: string | null; sold_at: string; total_amount: number; total_profit: number }
interface Purchase { id: number; reference: string | null; purchased_at: string; total_amount: number }
const movements = ref<Movement[]>([]); const sales = ref<Sale[]>([]); const purchases = ref<Purchase[]>([]); const movementPage = ref(1); const salePage = ref(1); const purchasePage = ref(1); const pageSize = 8; const error = ref(""); const loading = ref(true); const money = (value: number) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(value);
const pagedMovements = computed(() => movements.value.slice((movementPage.value - 1) * pageSize, movementPage.value * pageSize)); const pagedSales = computed(() => sales.value.slice((salePage.value - 1) * pageSize, salePage.value * pageSize)); const pagedPurchases = computed(() => purchases.value.slice((purchasePage.value - 1) * pageSize, purchasePage.value * pageSize));
async function load() { loading.value = true; error.value = ""; try { [movements.value, sales.value, purchases.value] = await Promise.all([invoke<Movement[]>("list_movements"), invoke<Sale[]>("list_sales_history"), invoke<Purchase[]>("list_purchases_history")]); movementPage.value = 1; salePage.value = 1; purchasePage.value = 1; } catch (e) { error.value = String(e); } finally { loading.value = false; } }
onMounted(load);
</script>

<template><section class="module-page"><div class="section-intro"><div><p class="eyebrow">Audit trail</p><h2>Riwayat operasional</h2><p class="intro-copy">Pergerakan stok dan transaksi disimpan untuk penelusuran operasional.</p></div><button class="secondary-button" type="button" @click="load"><RefreshCw :size="15" /> Segarkan</button></div><p v-if="error" class="form-error">{{ error }}</p><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">Inventori</p><h3>Pergerakan stok</h3></div><History :size="18" class="panel-icon" /></div><div v-if="loading" class="table-state">Memuat data...</div><div v-else-if="!movements.length" class="table-state">Belum ada pergerakan.</div><template v-else><table><thead><tr><th>Waktu</th><th>Varian</th><th>Jenis</th><th>Perubahan</th><th>Saldo</th><th>Alasan</th></tr></thead><tbody><tr v-for="item in pagedMovements" :key="item.id"><td>{{ item.moved_at }}</td><td class="cell-strong">{{ item.product_name }} / {{ item.variant_name }}</td><td>{{ item.movement_type }}</td><td :class="{ 'low-stock': item.quantity < 0 }">{{ item.quantity > 0 ? `+${item.quantity}` : item.quantity }}</td><td>{{ item.stock_after }}</td><td>{{ item.reason || item.reference || "—" }}</td></tr></tbody></table><PaginationControls v-model:page="movementPage" :total="movements.length" :page-size="pageSize" /></template></section><div class="content-columns history-columns"><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">Transaksi</p><h3>Penjualan</h3></div></div><div v-if="!sales.length" class="table-state">Belum ada penjualan.</div><template v-else><table><thead><tr><th>Tanggal</th><th>Referensi</th><th>Total</th><th>Laba</th></tr></thead><tbody><tr v-for="sale in pagedSales" :key="sale.id"><td>{{ sale.sold_at }}</td><td>{{ sale.reference || `#${sale.id}` }}</td><td>{{ money(sale.total_amount) }}</td><td>{{ money(sale.total_profit) }}</td></tr></tbody></table><PaginationControls v-model:page="salePage" :total="sales.length" :page-size="pageSize" /></template></section><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">Transaksi</p><h3>Pembelian</h3></div></div><div v-if="!purchases.length" class="table-state">Belum ada pembelian.</div><template v-else><table><thead><tr><th>Tanggal</th><th>Referensi</th><th>Total</th></tr></thead><tbody><tr v-for="purchase in pagedPurchases" :key="purchase.id"><td>{{ purchase.purchased_at }}</td><td>{{ purchase.reference || `#${purchase.id}` }}</td><td>{{ money(purchase.total_amount) }}</td></tr></tbody></table><PaginationControls v-model:page="purchasePage" :total="purchases.length" :page-size="pageSize" /></template></section></div></section></template>
